import 'dart:async';
import 'dart:convert';
class Graph {
  final List<List<int>> edges;
  final List<bool> visited;
  final List<int> parent;

  Graph(this.edges, int V) {
    this.visited = List.filled(V, false);
    this.parent = List.filled(V, -1);
    this.edges = List.generate(V, (_) => <int>[]);
  }

  void addEdge(int u, int v) {
    edges[u].add(v);
  }

  bool hasCycle() {
    final queue = <int>[];
    for (final node in parent) {
      if (node != -1) {
        queue.add(node);
      }
    }
    while (queue.isNotEmpty) {
      final u = queue.removeAt(0);
      if (visited[u]) return true;
      visited[u] = true;
      for (final v in edges[u]) {
        if (visited[v] && parent[u] != -1) return true;
        queue.add(v);
        parent[v] = u;
      }
    }
    return false;
  }

  void topSort() {
    if (hasCycle()) {
      print('Graph contains a cycle, topological sort not possible.');
      return;
    }
    final queue = <int>[];
    for (final node in parent) {
      if (node == -1) {
        queue.add(node);
      }
    }
    final result = <int>[];
    while (queue.isNotEmpty) {
      final node = queue.removeAt(0);
      result.add(node);
    }
    print('Topological Sort: ${result.join(' -> ')}');
  }
}

