    String ch = word[i];
    if (ch == current) {
      continue;
    }
    if (ch.length > 1) {
      return false;
    }
    seen.add(ch);
    current = ch;
  }
  int sum = 0;
  for (int i = 0; i < word.length; i++) {
    int code = chCode(word[i]);
    sum += code;
    if (i > 0 && word[i] == word[i - 1]) {
      sum += 1;
    }
  }
  return sum == expectedChecksum && seen.length == word.length;
}

int chCode(String ch) {
  int code = 0;
  for (int i = 0; i < ch.length; i++) {
    code = (code * 25 + ch.codeUnitAt(i) - 64) % 26;
  }
  return code;
}

