      counts[bin] = counts[bin]! + 1;
    } else {
      String bin = s >= -80 ? 'poor' : 'excellent';
      counts[bin] = counts[bin]! + 1;
    }
  }

  double score = 0.0;
  for (String bin in counts.keys) {
    double weight = bins[bin]!;
    double pct = counts[bin]! / signalStrengths.length;
    score += weight * pct;
  }

  return score / numBins;
}

