bool wordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<bool> dp = List<bool>.filled(s.length + 1, false);
  dp[0] = true;
  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[s.length];
}

List<List<String>> wordBreak2(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<List<String>> results = [];
  List<String> path = [];
  void backtrack(int start) {
    if (start == s.length) {
      results.add(List.from(path));
      return;
    }
    for (int j = start; j < s.length; j++) {
      if (wordSet.contains(s.substring(j, s.length))) {
        path.add(s.substring(j, s.length));
        backtrack(j + 1);
        path.removeLast();
      }
    }
  }
  backtrack(0);
  return results;
}

int minWordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<int> dp = List<int>.filled(s.length + 1, 0x7FFFFFFFFFFFFFFFF);
  dp[0] = 0;
  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] != 0x7FFFFFFFFFFFFFFFF && wordSet.contains(s.substring(j, i))) {
        int cost = dp[j] + 1;
        if (cost < dp[i]) dp[i] = cost;
      }
    }
  }
  return dp[s.length] == 0x7FFFFFFFFFFFFFFFF ? -1 : dp[s.length];
}

