Map<String, int> fn0(List<String> ops) {
  final Map<String, int> counts = {'BEGIN': 0, 'END': 0, 'ADD': 0, 'UNDO': 0};
  final List<int> history = [0];

  void add(int index, int value) {
    counts['ADD'] = counts['ADD']! + 1;
    history.add(value);
  }

  void undo() {
    if (history.length > 1) {
      final int last = history.removeLast();
      final int secondLast = history.removeLast();
      history.add(last);
      add(secondLast, last);
    } else {
      history.removeLast();
      counts['UNDO'] = counts['UNDO']! + 1;
    }
  }

  for (final op in ops) {
    if (op == 'BEGIN') {
      history.add(0);
      counts['BEGIN'] = counts['BEGIN']! + 1;
    } else if (op == 'END') {
      counts['END'] = counts['END']! + 1;
      history.add(0);
    } else if (op == 'ADD') {
      add(history.last, 0);
    } else if (op == 'UNDO') {
      undo();
    } else {
      final int value = int.parse(op);
      history.add(value);
      add(value, 0);
    }
  }

  final List<int> sorted = List<int>.from(history)..sort();
  final int current = sorted.last;
  final List<String> matches = [];
  for (final int v in sorted) {
    if (v == current) {
      matches.add(v.toString());
    } else if (v == current - 1) {
      matches.add('${v}-${current}');
    } else {
      matches.add(v.toString());
    }
  }
  return {'BEGIN': counts['BEGIN']!, 'END': counts['END']!, 'ADD': counts['ADD']!, 'UNDO': counts['UNDO']!, 'MATCHES': matches.length};
}

