String fn0(String playlist) {
  if (playlist.isEmpty) return "";
  Map<String, List<int>> history = {};
  List<String> trackNames = [];
  List<List<int>> stack = [];
  int totalDuration = 0;
  List<String> tokens = playlist.split(',');
  for (String token in tokens) {
    if (token.isEmpty) continue;
    List<String> parts = token.split(':');
    if (parts[0].equals('BEGIN')) {
      stack.add(parts[1].split('-'));
      history['BEGIN'] = (history['BEGIN'] ?? []) + [parts[1].split('-').length];
    } else if (parts[0].equals('END')) {
      if (stack.isEmpty) return "";
      String track = stack.removeLast()[0];
      trackNames.add(track);
      if (parts[1].isEmpty) totalDuration += 0;
      else {
        List<int> parts1 = parts[1].split('-');
        if (parts1.length < 2) return "";
        List<int> parts2 = parts1[1].split('-');
        totalDuration += (parts1[0].toInt() - parts2[0].toInt()).abs() * (parts2[1].toInt() - parts2[0].toInt()).abs();
        history['END'] = (history['END'] ?? []) + [parts1[0].toInt() - parts2[0].toInt() < 0 ? 1 : 0];
      }
    } else if (parts[0].equals('ADD')) {
      if (stack.isEmpty) return "";
      String track = stack.removeLast()[0];
      stack.add(parts[1].split('-'));
      history['ADD'] = (history['ADD'] ?? []) + [track.length];
    } else if (parts[0].equals('UNDO')) {
      if (stack.isEmpty) return "";
      String track = stack.removeLast()[0];
      trackNames.remove(track);
      history['UNDO'] = (history['UNDO'] ?? []) + [track.length];
    }
  }
  List<String> tracks = trackNames.toList()..sort();
  List<List<int>> durations = [];
  for (String track in tracks) {
    int count = history['BEGIN']?.where((e) => e == track.length) ?? 0;
    int undoCount = history['UNDO']?.where((e) => e == track.length) ?? 0;
    int addCount = history['ADD']?.where((e) => e == track.length) ?? 0;
    durations.add([count, undoCount, addCount]);
  }
  List<List<int>> result = List.generate(
    durations.length,
    (i) => [durations[i][0] + durations[i][1] - durations[i][2],
        durations[i][0] + durations[i][1] - durations[i][2] > 0 ? 1 : 0,
        durations[i][1]],
  );
  result.sort((a, b) => a[0].compareTo(b[0]));
  return totalDuration.toString() + ' ' + result[0][1].toString();
}

