void fn0() {

  String pattern = "EXAMPLE";
  List<String> text = ["HERE IS A SIMPLE EXAMPLE", "THIS IS A SIMPLY TEXT", "THIS IS A TEXT"];
  int numPatterns = pattern.length;
  int numTexts = text.length;

  List<int> lps = List<int>.filled(numPatterns, 0);

  int num = 0;
  int i = 1;

  while (i < numPatterns) {
    if (pattern[i] == pattern[num]) {
      num++;
      lps[i] = num;
      i++;
    }
    if (num != 0 && pattern[i] != pattern[num]) {
      num = lps[num - 1];
    }
  }

  List<String> results = [];
  for (int t = 0; t < numTexts; t++) {
    int m = text[t].length;
    List<bool> dp = List<bool>.filled(m + 1, false);
    dp[0] = true;

    for (int p = 0; p < numPatterns; p++) {
      List<int> mpp = List<int>.filled(m + 1, 0);
      int mppLen = lps[p];

      if (m > p) {
        if (dp[0]) {
          mpp[0] = true;
        }
      }

      int l = p + 1;
      int h = m - p;

      while (l <= h) {
        int mid = (l + h) >> 1;
        if (dp[mid]) {
          mpp[mid + 1] = true;
          h = mid - 1;
        } else {
          l = mid + 1;
        }
      }

      for (int len = mppLen; len <= m; len++) {
        if (mpp[len]) {
          if (len <= m) {
            dp[len] = true;
          }
        }
      }
    }

    if (dp[m]) {
      results.add("${text[t]} - ${pattern.length} matches: ${m}");
    }
  }

  if (results.isEmpty) {
    print("Pattern not found.");
  } else {
    print("Pattern found at positions: ${results.join(' ')}");
  }
}

