  ];

  Map<int, Set<int>> graphReverse = {};
  for (int i = 0; i < graph.length; i++) {
    Set<int> adjacent = graph[i].toSet();
    graphReverse[i] = adjacent;
  }

  int n = graph.length;
  List<bool> visited = List.filled(n, false);
  List<int> match = List.filled(n, 0);

