    List<bool> queue = List.filled(n, false);
    List<int> parent = List.filled(n, -1);
    queue[start] = true;
    parent[start] = start;

    while (queue.isNotEmpty) {
      int current = queue.removeLast();
      visited[current] = true;

      for (int neighbor in graphReverse[current]!) {
        if (!visited[neighbor]) {
          queue.add(neighbor);
          parent[neighbor] = current;
        }
      }
    }

    return parent[start] != -1;
  }

  int stableMatch(int start) {
    int count = 0;
    while (bfs(start)) {
      int temp = start;
      start = parent[temp];
      match[temp] = start;
      count++;
    }
    return count;
  }

  List<int> stable = List.filled(n, 0);
  for (int i = 0; i < n; i++) {
    if (stableMatch(i)) {
      stable[i] = 1;
    }
  }

  print('Stable matches:');
  for (int i = 0; i < n; i++) {
    if (stable[i] == 1) {
      print('W$i → X${match[i]}');
    }
  }
}

