    String b = dna[i];
    if (b == 'A' || b == 'T' || b == 'C' || b == 'G') {
      bases.add(b);
    }
  }

  Map<String, Map<String, int>> submaps = {};
  for (String b in bases) {
    Map<String, int> nextMap = {};
    Map<String, int> prevMap = {};
    for (String b2 in bases) {
      if (b == b2) continue;
      int lcsLen = lcsLen(b, b2);
      int overlap = dna.length - lcsLen;
      nextMap[b2] = (nextMap[b2] ?? 0) + 1;
      prevMap[overlap] = (prevMap[overlap] ?? 0) + 1;
    }
    submaps[b] = prevMap;
  }

  int count = 0;
  submaps.forEach((String b, Map<String, int> prev) {
    for (String b2 in bases) {
      if (b == b2) continue;
      int overlap = dna.length - lcsLen(b, b2);
      if (prev[overlap] == 1) {
        count += prevMap[overlap]!;
      }
    }
  });
  return count;
}

int lcsLen(String a, String b) {
  int n = a.length;
  int m = b.length;
  List<List<int>> dp = List.generate(
    n + 1,
    (_) => List.filled(m + 1, 0),
  );
  for (int i = 0; i <= n; i++) dp[i][0] = 0;
  for (int j = 0; j <= m; j++) dp[0][j] = 0;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (a[i - 1] == b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = dp[i - 1][j] > dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1];
      }
    }
  }
  return dp[n][m];
}

