int combinations(int n, int k) {
  if (k < 0 || k > n) return 0;
  if (k == 0 || k == n) return 1;

  int count = 0;
  int current = n - k;
  int last = n - k + 1;

  for (int i = 0; i <= current; i++) {
    int first = i;
    int rest = last - i;

    if (first >= 2 && rest >= 2) {
      count += combinations(first, 2) * combinations(rest, 2);
    }
  }
  return count;
}

