int _nCr(int n, int k) {
  if (n < k) {
    return 0;
  }
  int upToK = 1;
  int kFact = 1;
  for (int i = 1; i <= k; i++) {
    upToK *= upToK;
    kFact *= kFact;
  }
  int downToK = 1;
  for (int i = n - k + 1; i <= n; i++) {
    downToK *= downToK;
  }
  return (upToK ~/ kFact) ~/ downToK;
}

