class Graph<T> {
  final Map<T, Set<T>> graph;
  final Map<T, T> parent;
  final Map<T, int> rank;
  final Map<T, bool> visited;

  Graph(this.graph, {this.parent = {}, this.rank = {}, this.visited = {}});

  void dfs(T node, Set<T> visited) {
    visited.add(node);
    graph[node]!.forEach((neighbor) {
      if (!visited.contains(neighbor)) {
        parent[neighbor] = node;
        rank[neighbor] = rank[node]! > rank[neighbor]! ? rank[node]! : rank[neighbor]!;
        dfs(neighbor, visited);
      }
    });
  }

  void dfsPostorder(T node, Set<T> visited) {
    visited.add(node);
    graph[node]!.forEach((neighbor) {
      if (!visited.contains(neighbor)) {
        dfsPostorder(neighbor, visited);
      }
    });
    visited.add(node);
  }

  void bfs(T node) {
    final queue = <T>[node];
    visited[node] = true;
    while (queue.isNotEmpty) {
      final current = queue.removeAt(0);
      graph[current]!.forEach((neighbor) {
        if (!visited[neighbor]!) {
          visited[neighbor] = true;
          queue.add(neighbor);
        }
      });
    }
  }

  bool hasPath(T from, T to, List<T> path) {
    if (from == to) {
      path.add(from);
      return true;
    }
    visited[from] = true;
    if (graph[from]!.containsKey(to)) {
      path.add(from);
      return true;
    }
    for (final neighbor in graph[from]!) {
      if (!visited[neighbor]! && hasPath(neighbor, to, path)) {
        return true;
      }
    }
    return false;
  }
}

