import 'dart:async';
import 'dart:convert';
class Graph {
  final Map<int, List<int>> adjacency;
  final Map<int, Set<int>> adjacencyInverse;
  final int n;
  final List<int> parent;
  final Set<int> visited;

  Graph(this.n, this.adjacency, this.adjacencyInverse);

  void explore(int v, Set<int> visited, List<int> stack) {
    visited.add(v);
    stack.add(v);
    for (int w in adjacency[v] ?? <int>[]) {
      if (!visited.contains(w)) {
        parent[w] = v;
        explore(w, visited, stack);
      }
    }
    stack.removeLast();
  }

  void dfs() {
    final Stack<int> stack = Stack<int>();
    final List<int> stackRoots = [];
    for (final v in adjacency.keys) {
      if (!visited.contains(v)) {
        stack.clear();
        stackRoots.add(v);
        explore(v, visited, stack);
      }
    }
  }

  void iterative() {
    final List<int> stack = <int>[];
    for (final v in adjacency.keys) {
      if (!visited.contains(v)) {
        stack.add(v);
      }
      while (stack.isNotEmpty) {
        final v = stack.removeLast();
        visited.add(v);
        for (final w in adjacency[v] ?? <int>[]) {
          if (!visited.contains(w)) {
            stack.add(w);
          }
        }
      }
    }
  }

  void printGraph(int depth) {
    printGraphRec(adjacency, adjacencyInverse, 0, '', depth);
  }

  void printGraphRec(Map<int, List<int>> graph, Map<int, Set<int>> inverse, int depth, String prefix, int maxDepth) {
    if (depth >= maxDepth || graph.isEmpty) return;
    for (final v in graph.keys) {
      print('$prefix$v: ${graph[v]}');
      printGraphRec(graph, inverse, depth + 1, '$prefix  ', maxDepth);
    }
  }
}

