import 'dart:async';
import 'dart:convert';
class TreeNode {
  final int value;
  final List<TreeNode> children;

  TreeNode(this.value, [this.children = const []]);
}

class BinaryTreeSearch {
  final Map<int, TreeNode> tree = {};

  void insert(int value) {
    TreeNode? newNode = tree[value];
    if (newNode != null) return;

    TreeNode? parent;
    TreeNode? node;
    for (int? v in tree.keys) {
      if (v == value) {
        return;
      }
      parent = v;
      node = v;
    }
    if (node != null) return;

    TreeNode? sibling = tree[parent]!.children.isEmpty ? null : tree[parent]!.children.last;
    if (sibling != null) {
      sibling.children.add(newNode);
    } else {
      parent!.children.add(newNode);
    }
  }

  bool search(int value) {
    TreeNode? node = tree[value];
    return node != null;
  }

  void print(TreeNode? node, int depth) {
    if (node == null) return;
    print('$node:${node.value}');
    for (TreeNode child in node.children) {
      print('  ' * depth + '|');
      print('$child:${child.value}');
      print('  ' * depth + '|');
      print('$child:${child.value}');
      print('  ' * depth + '|');
      print('$child:${child.value}');
    }
