        bool safe = true;

        for (int i = 0; i < row; i++) {
          if (board[i][col] == 1) {
            safe = false;
            break;
          }
        }
        if (safe) {
          result[row][col] = 1;
          result = result + place(row + 1);
        }
      }
      return result;
    }

    bool isSafe(int row, List<List<int>> board, int col) {
      for (int i = 0; i < row; i++) {
        if (board[i][col] == 1) return false;
      }
      for (int i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--) {
        if (board[i][j] == 1) return false;
      }
      for (int i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++) {
        if (board[i][j] == 1) return false;
      }
