import 'dart:convert';
class Queen {
  final int row;
  final int col;

  Queen(this.row, this.col);

  @override
  String toString() => 'Q$row$col';
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  int n;
  if (args.isEmpty || args.last.isEmpty) {
    n = 8; 
  } else {
    final nStr = args.last;
    n = int.parse(nStr);
    if (n <= 0) {
      print('N must be a positive integer.');
      return;
    }
  }

  final int rows = n;
  final int cols = n;

  final List<Queen> queens = List.generate(rows, (i) => Queen(i, -1));

  final List<String> solution = List.filled(rows, '');
  var file = 0;
  var rank = 0;
  var row = -1;
  var cols = List.filled(n, 0);
  for (var i = 0; i < rows; i++) {
    if (file < cols.length && cols[file] == 0) {
      file = i;
      rank = 0;
      row = -1;
      cols = List.filled(n, 0);
    }
    if (file < cols.length && cols[file] == 0) {
      cols[file] = 1;
      solution[rank] += '${queen.toString()}$file';
      file++;
      rank = 0;
    } else {
      file = 0;
    }
  }

  int total = 0;
  void backtrack(List<Queen> queens, List<String> solution) {
    if (solution.length == queens.length) {
      total++;
      print('Solution $total:');
      for (var i = 0; i < queens.length; i++) {
        print(solution[i]);
      }
      print('--------------------------------');
      return;
    }
    for (var i = 0; i < queens.length; i++) {
      if (queens[i].row == -1) {

        final int newRow = queens.length - 1 - i;
        if (queens[newRow].col == -1) {

          final int newCol = file;
          queens[newRow] = Queen(newRow, newCol);
          queens[i] = Queen(i, newRow);
          solution[queens.length - 1] += '${queen.toString()}$newCol';
          backtrack(queens, solution);
          queens[newRow] = Queen(newRow, -1);
          queens[i] = Queen(i, -1);
          continue;
        }

        for (var j = 0; j < queens.length; j++) {
          if (queens[j].col == newCol) {
            break;
          }
          if (queens[j].row == newRow) {
            break;
          }
          if (newCol - queens[j].col == newRow - queens[j].row) {
            break;
          }
        }
        if (j < queens.length) {
          continue;
        }
      }
    }
  }

  backtrack(queens, solution);
  print('Total solutions: $total');
}

