@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  final int n = args.isNotEmpty ? int.parse(args[0]) : 8;

  final List<List<int>> solutions = [];
  final bool solve(int row) {

    if (row == n) {
      solutions.add(List.generate(n, (i) => i + 1));
      return true;
    }

    for (int col = 0; col < n; col++) {
      if (solutions.isEmpty) {
        continue;
      }

      final List<List<int>> prev = solutions.removeLast();
      prev[row] = col;
      solutions.add(prev);

      if (solve(row + 1)) {
        return true;
      }

      prev[row] = -1;
      solutions.removeLast();
    }
    return false;
  }

  if (!solve(0)) {
    print('Solving N-Queens for N=$n...');
    print('Total solutions: ${solutions.length}');
  } else {
    print('Solving N-Queens for N=$n...');
    print('Total solutions: ${solutions.length}');
    print('Solution ${solutions.length + 1}:');
    for (final List<int> solution in solutions) {
      print('Q ${solution.map((c) => c.toString()).join(' ')}');
    }
  }
}

