void fn0(List<String> args) {

  final int N = args.isEmpty ? 8 : int.parse(args[0]);

  bool isSafe(List<int> queenPos, int r, int c) {
    for (int i = 0; i < r; i++) {
      if (queenPos[i] == c) return false;
      if (queenPos[i] == (r - i)) return false;
    }
    return true;
  }

  int totalSolutions = 0;

  void solve(List<int> queenPos, int r) {
    if (r == N) {
      totalSolutions++;
      printSolution(queenPos);
      return;
    }

    for (int c = 0; c < N; c++) {
      if (isSafe(queenPos, r, c)) {
        queenPos[r] = c;
        solve(queenPos, r + 1);
      }
    }
  }

  List<int> queenPos = List.filled(N, -1);
  solve(queenPos, 0);
  print('Total solutions: $totalSolutions');
}

void printSolution(List<int> queenPos) {
  String board = '';
  for (int r = 0; r < N; r++) {
    if (queenPos[r] == -1) board += '.';
    else board += 'Q ';
  }
  print('Solution $board');
}

