class Quaternion {
  final double real;
  final List<double> imaginary;

  Quaternion(this.real, [this.imaginary = [0.0, 0.0, 0.0, 0.0]]);

  /// Returns a new quaternion with real part 0 and imaginary parts as this quaternion.
  @override
  String toString() => 'Quaternion($real $imaginary)';

  /// Adds two quaternions.
  /// Uses the standard quaternion addition formula.
  Quaternion operator +(Quaternion other) =>
      Quaternion(real + other.real, [x + other.x, y + other.y, z + other.z, w + other.w]);

  /// Subtracts two quaternions.
  /// Uses the standard quaternion subtraction formula.
  Quaternion operator -(Quaternion other) =>
      Quaternion(real - other.real, [x - other.x, y - other.y, z - other.z, w - other.w]);

  /// Multiplies two quaternions.
  /// Uses the standard quaternion multiplication formula.
  Quaternion operator *(Quaternion other) =>
      Quaternion(real * other.real - (x * other.x + y * other.y + z * other.z + w * other.w),
          [
            (x * other.y + y * other.x) + (z * other.z - w * other.w),
            (x * other.z + y * other.w) + (z * other.x - w * other.y),
            (x * other.w + y * other.z) + (z * other.y - w * other.x),
            x * other.w + y * other.w + z * other.w
          ]);

  /// Returns the complex conjugate of this quaternion.
  Quaternion get conjugate =>
      Quaternion(real, [x, y, z, -w]);

  /// Returns the magnitude (norm) of this quaternion.
  double get norm => sqrt(real * real + x * x + y * y + z * z + w * w);

  /// Normalizes this quaternion, i.e., sets w = 0 and scales so that the norm equals 1.
  /// Raises an ArgumentError if the norm is 0.
  Quaternion get normalized =>
      Quaternion(real / norm, [x / norm, y / norm, z / norm, 0.0]);

  /// Returns the inverse of this quaternion.
  /// Raises an ArgumentError if the real part is 0.
  Quaternion get inverse =>
      Quaternion(real == 0 ? 0.0 : 1.0 / (real * real + x * x + y * y + z * z + w * w),
          [
            -x / (real * real + x * x + y * y + z * z + w * w),
            -y / (real * real + x * x + y * y + z * z + w * w),
            -z / (real * real + x * x + y * y + z * z + w * w),
            -w / (real * real + x * x + y * y + z * z + w * w)
          ]);
}

