class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator *(Quaternion other) {
    return Quaternion(
      x * other.x - y * other.y - z * other.z - w * other.w,
      x * other.y + y * other.x + z * other.w - w * other.z,
      x * other.z - y * other.w + z * other.x + w * other.y,
      x * other.w + y * other.z - z * other.x + w * other.y,
    );
  }

  double get norm => (x * x + y * y + z * z + w * w).sqrt;

  Quaternion get conjugate => Quaternion(x, y, z, -w);

  Quaternion get inverse => Quaternion(x, y, z, 1 / (x * x + y * y + z * z + w * w));

  Quaternion get normalized => this.clone() * norm.inv;

  factory Quaternion.fromAxisAngle(double angle, double axisX, double axisY, double axisZ) {
    double c = cos(angle / 2);
    double s = sin(angle / 2);
    return Quaternion(c * axisX, c * axisY, c * axisZ, s);
  }

  @override
  String toString() {
    return '(${x}, ${y}, ${z}, ${w})';
  }

  factory Quaternion.fromRotation(double x, double y, double z, double w) {
    return Quaternion(x, y, z, w);
  }

  factory Quaternion.fromEuler(double x, double y, double z) {
    return Quaternion.fromAxisAngle(x, 1, 2, 3) *
           Quaternion.fromAxisAngle(y, 1, 2, 3) *
           Quaternion.fromAxisAngle(z, 1, 2, 3);
  }

  factory Quaternion.fromMat3(List<List<double>> mat) {
    return Quaternion.fromEuler(
      mat[0][0], mat[1][0], mat[2][0],
      mat[0][1], mat[1][1], mat[2][1],
      mat[0][2], mat[1][2], mat[2][2],
    );
  }

  factory Quaternion.fromMat4(List<List<double>> mat) {
    return Quaternion.fromEuler(
      mat[0][0], mat[1][0], mat[2][0],
      mat[0][1], mat[1][1], mat[2][1],
      mat[0][2], mat[1][2], mat[2][2],
      mat[0][3], mat[1][3], mat[2][3],
    );
  }

  factory Quaternion.fromQuat(List<double> q) {
    return Quaternion(q[0], q[1], q[2], q[3]);
  }
}

