String fn0(List<String> commands) {
  List<int> stack = [];
  int result = 0;
  for (final cmd in commands) {
    if (cmd == 'OPEN') {
      stack.add(0);
    } else if (cmd == 'CLOSE') {
      if (stack.isEmpty) result -= 1;
      else stack.removeLast();
    } else if (cmd == 'D:n') {
      if (stack.isEmpty) result -= 1;
      else stack.add(stack.last + int.parse(cmd.substring(2)));
    } else if (cmd == 'C:c') {
      if (stack.isEmpty) result -= 1;
      else stack.add(stack.last - int.parse(cmd.substring(2)));
    }
  }
  final history = stack.join(' ');
  final net = stack.isEmpty ? 0 : stack.last;
