String endian() {
  final ByteData bytes = Uint32.buffer(1).setUint32(0, 0x12345678, Endian.big);
  final ByteData reversed = Uint32.buffer(1).setUint32(0, 0x12345678, Endian.little);
  final ByteData swapped = Uint32.buffer(1).setUint32(0, 0x12345678, Endian.big).buffer;
  final ByteData reversedSwapped = Uint32.buffer(1).setUint32(0, 0x12345678, Endian.little).buffer;

  for (var i = 0; i < bytes.length; i++) {
    if (bytes.getUint32(i, Endian.big) != reversedSwapped.getUint32(i, Endian.big)) {
      return "big-endian";
    }
    if (bytes.getUint32(i, Endian.little) != reversedSwapped.getUint32(i, Endian.little)) {
      return "little-endian";
    }
  }
  throw ArgumentError("Cannot determine endianness");
}

