List<int> fn0(List<int> dice, int target) {
  if (target <= 0 || dice.isEmpty) return [0, 0];
  List<int> dp = List.filled(target + 1, 0);
  int sum = 0;
  for (int i = 0; i < dice.length; i++) {
    sum += dice[i];
    for (int j = target; j >= sum; j--) {
      dp[j] = (dp[j] + 1) % 2;
    }
  }
  int bestStart = 0, bestEnd = 0;
  for (int j = target; j >= sum; j--) {
    if (dp[j] == 1) {
      bestStart = sum;
      bestEnd = j;
      break;
    }
  }
  return [bestStart, bestEnd];
}

