  int cols = grid[0].length;
  if (rows == 0 || cols == 0) return [];
  int total = rows * cols;
  int totalIdx = 0;
  List<int> indices = List.filled(total, 0);
  for (int c = 0; c < cols; c++) {
    for (int r = 0; r < rows; r++) {
      indices[totalIdx] = c * rows + r;
      totalIdx++;
    }
  }
  int totalWeight = 0;
  for (int i = 0; i < indices.length; i++) {
    int val = grid[indices[i] ~/ cols][indices[i] % cols];
    totalWeight += val;
  }
  return [totalWeight, totalIdx];
}

