List<int> fn0(List<int> phaseDurations) {
  if (phaseDurations.isEmpty) return [];
  int n = phaseDurations.length;
  int total = 0;
  for (int i = 0; i < n; i++) {
    total += phaseDurations[i];
  }
  List<int> dp = List.filled(n + 1, 0);
  dp[0] = 0;
  for (int i = 1; i <= n; i++) {
    dp[i] = dp[i - 1];
    int best = 0;
    for (int j = 0; j <= i; j++) {
      if (dp[j] > best) best = dp[j];
    }
    dp[i] += best + phaseDurations[i - 1];
  }
  return dp;
}

