void fn0() {

  final roleData = <String, List<String>>{
    'admin': ['read', 'write', 'delete', 'admin'],
    'editor': ['read', 'write'],
    'moderator': ['read', 'write', 'delete'],
    'viewer': ['read'],
  };

  final resources = <String, List<String>>{
    'document1': ['read'],
    'document2': ['read', 'write'],
    'adminResource': ['read', 'write', 'delete', 'admin'],
  };

  final users = <String, Map<String, int>>{
    'alice': {
      'role': 'editor',
      'permissions': 3,
    },
    'bob': {
      'role': 'moderator',
      'permissions': 3,
    },
    'charlie': {
      'role': 'viewer',
      'permissions': 1,
    },
    'diana': {
      'role': 'editor',
      'permissions': 3,
    },
  };

  final actionLogs = <String, int>{};


  const String currentRole = 'editor';
  final String currentResource = 'document1';


  final permissions = <String, int>{
    'read': 1,
    'write': 2,
    'delete': 4,
    'admin': 8,
  };

  void logAction(String action, String resource, String user, String role, int timestamp) {
    actionLogs['$action'] = (actionLogs['$action'] ?? 0) + 1;
    print('[$timestamp] $user $action $resource ($role) -> ${actionLogs['$action']} attempts to');
  }

  bool checkPermission(String role, String action, String resource) {
    final rolePermissions = roleData[role] ?? [];
    if (rolePermissions.isEmpty) return false;
    if (action == 'admin') {
      return true;
    }
    if (resources.containsKey(resource) && resources[resource]!.contains(action)) {
      return true;
    }
    final granted = rolePermissions.firstWhere((p) => permissions[p] != null && permissions[p]! & action != 0);
    return granted != null && permissions[granted]! & action != 0;
  }

  void denyAccess(String user, String resource, String action) {
    print('  ❌ Access DENIED (Insufficient permissions)');
    print('  ❌ User "$user" could not access "$resource" using "$action"');
  }

  void grantAccess(String user, String resource, String action) {
    print('  ✅ Access GRANTED (Role: "$currentRole")');
    print('  ✅ User "$user" can access "$resource" using "$action"');
    logAction(action, resource, user, currentRole, DateTime.now().millisecondsSinceEpoch);
  }

  bool checkRole(String role) {
    return roleData.containsKey(role);
  }

  bool addRole(String role, String... permissions) {
    if (checkRole(role)) return false;
    roleData[role] = permissions;
    return true;
  }

  bool removeRole(String role) {
    return roleData.remove(role) != null;
  }

  void updateRole(String user, String oldRole, String newRole) {
    if (!checkRole(oldRole) || !checkRole(newRole)) return;
    users[user] = (users[user] ?? <String, int>{});
    users[user]![newRole] = (users[user]![newRole] ?? 0) + 1;
    users[user]!.remove(oldRole);
  }

  bool hasPermission(String user, String action, String resource) {
    if (!users.containsKey(user)) return false;
    final u = users[user]!;
