int swapBytes(int value) {
  return ((value >> 24) & 0xFF) |
         ((value >> 16) & 0xFF) << 16 |
         ((value >> 8) & 0xFF) << 8 |
         (value & 0xFF);
}

int swap16Bits(int value) {
  return ((value >> 16) & 0xFFFF) |
         ((value >> 8) & 0xFFFF) << 16;
}

int swap32Bits(int value) {
  return ((value >> 24) & 0xFF) |
         ((value >> 16) & 0xFF) << 16 |
         ((value >> 8) & 0xFF) << 8 |
         (value & 0xFF);
}

int convertBigToLittle(int value) {
  int reversed = 0;
  int i = 31;
  while (i >= 0) {
    reversed = (reversed << 1) | ((value >> i) & 1);
    i--;
  }
  return reversed;
}

int convertLittleToBig(int value) {
  int reversed = 0;
  int i = 31;
  while (i >= 0) {
    reversed = (reversed << 1) | ((value >> i) & 1);
    i--;
  }
  return reversed;
}

