void fn0() {

  Set<int> transactions = {
    [1, 2, 3], [2, 3, 4], [1, 3, 4], [1, 2],
    [2, 3], [3, 4], [1, 2, 4], [1, 2, 3, 4],
  };

  const int minSupport = 2; 
  const int minConfidence = 0.7; 

  Map<Set<int>, int> itemFrequencies = {};
  Map<int, Set<int>> frequentItemsets = {};

  for (int t in transactions) {
    int hash = t.map((i) => i).hashCode;
    itemFrequencies[t] = (itemFrequencies[t] ?? 0) + 1;
  }

  for (int t in itemFrequencies.entries) {
    int count = t.value;
    if (count >= minSupport) {
      Set<int> items = t.key.toSet();
      int hash = items.map((i) => i).hashCode;
      if (!frequentItemsets.containsKey(hash)) {
        frequentItemsets[hash] = <int>{};
      }
      frequentItemsets[hash]!.add(items);
    }
  }

  List<List<int>> frequentItemsetsList = frequentItemsets.entries
      .map((e) => e.value.toList()..sort())
      .toList();

  print('Frequent Itemsets:');
  for (int i = 1; i < frequentItemsetsList.length; i++) {
    print('-'.repeat(40));
  }
  for (var itemset in frequentItemsetsList) {
    print(itemset.map((i) => '${items[i]}).join(' | '));
  }

  Map<List<int>, List<int>> itemSetsWithRules = {};
  for (var itemset in frequentItemsetsList) {
    int hash = itemset.map((i) => i).hashCode;
    itemSetsWithRules[hash] = <List<int>>[];
  }

  for (var itemset in frequentItemsetsList) {
    for (int k = 2; k <= itemset.length; k++) {

      List<int> frequentSubset = itemset.toSet().where((i) => i < k).toList();
      List<int> frequentComplement = itemset.toSet().where((i) => i >= k).toList();
      if (frequentSubset.isNotEmpty && frequentComplement.isNotEmpty) {
        int hash = frequentComplement.map((c) => c).hashCode;
        itemSetsWithRules[hash]!.add(itemset);
      }
    }
  }

  for (var rules in itemSetsWithRules.entries) {
    List<List<int>> frequentComplement = rules.value.toList()..sort();
    List<int> itemset = rules.key.toList()..sort();
    if (frequentComplement.length != itemset.length) {
      continue;
    }
    for (int i = 0; i < frequentComplement.length; i++) {
      int item = frequentComplement[i];
      int complement = itemset.length - 1 - item;
      if (item < 0 || item > itemset.length - 1) {
        continue;
      }
      int left = frequentComplement.toSet().contains(itemset[i]) ? itemset[i] : -item;
      int right = frequentComplement.toSet().contains(itemset[itemset.length - 1 - i]) ? itemset[itemset.length - 1 - i] : -item;
      double confidence = (frequentItemsets[itemset[i]] ?? 0) / (frequentItemsets[complement] ?? 0);
      if (confidence >= minConfidence) {
        print('Association Rules:');
        print('-'.repeat(40));
        print('$left -> $right (support: ${frequentItemsets[itemset[i]] ?? 0}, confidence: $confidence)');
      }
    }
  }
}

