  int minSupport = 2; 
  int minConfidence = 0.7; 

  for (var itemset in items) {
    int support = 0;
    for (var transactions in transactions) {
      if (transactions.contains(itemset)) {
        support++;
      }
    }
    if (support >= minSupport) {
      freq[itemset] = support;
    }
  }

  List<List<String>> frequent = freq.entries
      .where((e) => e.key.length >= 2)
      .map((e) => e.key.toList())
      .toList();

  Map<List<String>, Set<List<String>>> associationRules = {};
  for (var itemset in frequent) {
    for (var superset in itemset.toList()) {
      var candidate = [superset];
      associationRules[superset] = (associationRules[superset] ?? <List<String>>{});

      for (var item in candidate) {
        if (item.length > 2) {
          break; 
        }

        var conf = (freq[itemset] ?? 0) / (freq[item] ?? 0);
        if (conf >= minConfidence) {
          associationRules[superset]!.add(item);
        }
      }
    }
  }

  print('Frequent Itemsets:');
  for (var itemset in frequent) {
    print(itemset.join(' ') + ' (support: ${freq[itemset]!})');
  }
  print('\nAssociation Rules:');
  for (var itemset in frequent) {
    for (var rhs in associationRules[itemset]!) {
      print(itemset.join(' ') + ' -> ${rhs.join(' ')} (confidence: ${minConfidence})');
