    ['Bread', 'Butter', 'Chocolate'],
    ['Bread', 'Chocolate'],
    ['Milk', 'Butter', 'Chocolate'],
    ['Bread', 'Milk', 'Butter', 'Chocolate', 'Sugar'],
  };

  final double minSupport = 0.5;

  final Map<List<String>, int> frequentItemsets = {};

  final Set<List<String>> frequentItemsetsSet = {};

  void scanTransactions(List<String> items) {
    final int n = items.length;
    final Set<List<String>> unique = {};
    for (final transaction in transactions) {
      if (transaction.length != n) continue;
      final List<String> transactionItems = transaction.toList();
      bool allPresent = true;
      for (final item in items) {
        if (!transactionItems.contains(item)) {
          allPresent = false;
          break;
        }
      }
      if (!allPresent) continue;
      unique.add(transactionItems);
    }
    final List<List<String>> uniqueItems = unique.toList();
    uniqueItems.sort();
    for (final item in uniqueItems) {
      final int count = (frequentItemsets[item] ?? 0) + 1;
      frequentItemsets[item] = count;
      if (count >= minSupport) {
        frequentItemsetsSet.add(item);
      }
    }
  }

  scanTransactions(['Bread', 'Milk', 'Butter', 'Chocolate']);
  scanTransactions(['Bread', 'Butter', 'Chocolate']);
  scanTransactions(['Milk', 'Butter', 'Chocolate']);
  scanTransactions(['Bread', 'Milk', 'Butter', 'Chocolate', 'Sugar']);

  print('Frequent Itemsets:');
  print(frequentItemsetsSet.map((itemset) => itemset.join(' ')).toList());

  print('\nAssociation Rules:');
  final Map<String, List<String>> frequentRuleCandidates = {};
  final Map<String, int> ruleCandidatesFrequency = {};

  void generateAssociationRules(String left, List<String> rightItems) {
    if (rightItems.isEmpty) return;
    final String candidate = left + ',' + rightItems.join(',');
    final int freq = (ruleCandidatesFrequency[candidate] ?? 0) + 1;
    ruleCandidatesFrequency[candidate] = freq;
    if (freq >= minSupport) {
      frequentRuleCandidates[candidate] ??= [];
      frequentRuleCandidates[candidate]!.add(candidate);
    }
    for (final item in rightItems) {
      final int newRight = rightItems.without(item);
      generateAssociationRules(left + ',' + item, newRight);
    }
  }

  void generateCandidates(List<String> items) {
    final int n = items.length;
    if (n == 1) {
      scanTransactions(items);
      return;
    }
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        final List<String> left = items.sublist(0, i);
        final List<String> right = items.sublist(i + 1);
        final List<String> itemsLeft = left.toList();
        final List<String> itemsRight = right.toList();
        if (itemsLeft.length > right.length) {
          final temp = left;
          left = right;
          right = temp;
        }
        generateAssociationRules(itemsLeft, right);
      }
    }
  }

  generateCandidates(['Bread', 'Milk', 'Butter', 'Chocolate']);
  for (final entry in frequentRuleCandidates.entries) {
    final String left = entry.key.split(',')[0];
    final List<String> rightItems = entry.key.split(',').sublist(1);
    final double confidence = (frequentItemsets[left] ?? 0) / (frequentItemsets[left + ',' + rightItems.join(',')] ?? 0);
    print('$left => $rightItems (support: ${(frequentItemsets[left] ?? 0) / transactions.length}, confidence: $confidence)');
  }
}

