  for (int i = 0; i < n; i++) {
    int left = bins[i];
    if (left == 0) continue;
    int right = prev[left];
    if (right == 0) continue;
    int gap = i - right;
    if (gap > best) best = gap;
  }
  return [best, bins];
}

