List<int> fn0(List<List<int>> grid) {
  int rows = grid.length;
  if (rows == 0 || grid[0].length == 0) return [];

  List<int> dp = List.filled(rows + 1, 0);
  List<int> best = List.filled(rows + 1, 0);

  for (int i = 1; i <= rows; i++) {
    dp[i] = dp[i - 1] + grid[i - 1][0];
    if (i >= 2) {
      dp[i] = dp[i] > dp[i - 2] + grid[i - 2][0] ? dp[i] : dp[i - 2] + grid[i - 2][0];
    }

    if (dp[i] > best[i]) {
      best[i] = dp[i];
    }
  }

  List<int> result = [];
  int index = rows;

  while (index > 1) {
    if (dp[index] > dp[index - 1]) {
      result.add(grid[index - 1][0]);
    } else {
      result.add(grid[index - 2][0]);
    }
    index--;
  }

  result.add(grid[0][0]);
  return result;
}

