  }

  double overlap(Point<double> a, Point<double> b) {
    double left = min(a.x, b.x);
    double right = max(a.x, b.x);
    if (right <= left) return 0.0;
    double bottom = min(a.y, b.y);
    double top = max(a.y, b.y);
    if (top <= bottom) return 0.0;
    return (right - left) * (top - bottom);
  }

  double overlapArea(Point<double> a, Point<double> b, Point<double> c, Point<double> d) {
    double sa = 0.0;
    sa += overlap(a, b);
    sa += overlap(b, c);
    sa += overlap(c, a);
    sa -= overlap(a, c);
    return sa;
  }

  double distance(Point<double> a, Point<double> b) {
    double dx = (a.x - b.x).abs();
    double dy = (a.y - b.y).abs();
    return sqrt(dx * dx + dy * dy);
  }

  double distToRectangle(Point<double> p) {
    double dx = min(p.x, 200.0) - max(p.x, 0.0);
    double dy = min(p.y, 200.0) - max(p.y, 0.0);
    if (dx <= 0 && dy <= 0) return 0.0;
    return sqrt(dx * dx + dy * dy);
  }

