void fn0() {

  final rng = Random(0);

  const int k = 7;
  const int maxIter = 100;
  const double epsilon = 1.0e-4;
  const double weight = 2.0;
  const double alpha = 1.0;

  List<List<double>> points = [
    [1.0, 1.5],
    [1.5, 2.0],
    [2.5, 2.0],
    [2.0, 2.5],
    [3.0, 3.5],
    [4.0, 4.5],
    [5.0, 7.0],
  ];

  Set<int> clusterLabel = {0, 0, 0, 0, 0, 0, 0};
  List<int> clusterLabelList = List<int>.filled(k, 0);
  double distance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      sum += pow(a[i] - b[i], 2);
    }
    return sqrt(sum);
  }

  double centroidWeight(int idx) {
    return 1.0 + weight * points[idx].length;
  }

  int updateClusterLabel(List<double> point) {
    int bestIdx = -1;
    double bestDist = double.infinity;
    for (int i = 0; i < k; i++) {
      double dist = distance(point, points[i]);
      if (dist < bestDist) {
        bestDist = dist;
        bestIdx = i;
      }
    }
    return bestIdx;
  }

  double calcLabelWeight(int idx, int label) {
    return 1.0 + weight * clusterLabelList[label];
  }

  double calcDist(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      sum += pow(a[i] - b[i], 2);
    }
    return sqrt(sum);
  }

  int calcCluster(List<double> point) {
    int bestIdx = -1;
    double bestDist = double.infinity;
    for (int i = 0; i < k; i++) {
      double dist = calcDist(point, points[i]);
      if (dist < bestDist) {
        bestDist = dist;
        bestIdx = i;
      }
    }
    return bestIdx;
  }

  double updateLabels(List<double> point) {
    int clusterIdx = updateClusterLabel(point);
    if (clusterIdx == -1) {
      return 0.0;
    }

    int oldClusterIdx = calcCluster(point);
    if (oldClusterIdx == -1) {
      return 0.0;
    }

    double change = 0.0;
    if (oldClusterIdx != clusterIdx) {
      change += alpha * centroidWeight(oldClusterIdx);
    }

    change += alpha * calcLabelWeight(oldClusterIdx, oldClusterIdx);
    change -= alpha * calcLabelWeight(oldClusterIdx, clusterIdx);
    if (oldClusterIdx != clusterIdx) {
      change += alpha * centroidWeight(clusterIdx);
    }

    clusterLabelList[oldClusterIdx] -= alpha;
    clusterLabelList[clusterIdx] += alpha;
    clusterLabel = {for (int i = 0; i < k; i++) clusterLabel[i] + 1};

    return change;
  }

  double totalChange = 0.0;
  int iter = 0;
  while (totalChange >= epsilon && iter < maxIter) {
    for (int i = 0; i < points.length; i++) {
      List<double> point = points[i];

      double weight = centroidWeight(i);

      if (clusterLabel[i] == 0) {
        clusterLabel[i] = calcCluster(point);
        clusterLabelList[clusterLabel[i]] += 1;
      }

      double change = updateLabels(point);
      totalChange += change;
      iter++;
    }
  }

  print('Converged in $iter iteration(s).');
  print('Cluster ');
  for (int i = 0; i < k; i++) {
    print('$i: ${clusterLabel[i]}');
  }
  print('  Points: ${points.map((p) => p.join(',')).toList()}');
  for (int i = 0; i < k; i++) {
    print(' centroid: ${points[i]}');
  }
}

