    [7.0, 1.5],
  ];

  int k = 2; 
  int numClusters = points.length;

  if (k < 1 || k > numClusters) {
    print('Invalid number of clusters. Aborting...');
    return;
  }

  List<int> cluster = List.filled(numClusters, 0);
  List<double> centroid = List.filled(2, 0.0);

  double distance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < 2; i++) {
      sum += pow(a[i] - b[i], 2);
    }
    return sqrt(sum);
  }

  while (true) {

    double minDist = double.infinity;
    for (int i = 0; i < numClusters; i++) {
      for (int j = i + 1; j < numClusters; j++) {
        double d = distance(points[i], points[j]);
        if (d < minDist) {
          minDist = d;
          cluster[i]++;
          cluster[j]++;
        } else if (d == minDist && points[i].length < points[j].length) {
          cluster[i]++;
        } else if (d == minDist && points[i].length > points[j].length) {
          cluster[j]++;
        }
      }
    }

    for (int i = 0; i < numClusters; i++) {
      if (cluster[i] > 0) {
        centroid[0] += points[i].fold(0.0, (a, b) => a + b) / cluster[i];
        centroid[1] += points[i].fold(0.0, (a, b) => a + b) / cluster[i];
      }
    }

    int iterations = 0;
    double bestDist = double.infinity;
    while (true) {

      double dist = 0.0;
      for (int i = 0; i < numClusters; i++) {
        if (cluster[i] > 0) {
          dist += distance(points[i], centroid);
        }
      }
      if (dist > bestDist) {
        bestDist = dist;
      }

      if (bestDist == 0.0) {
        break;
      }

      for (int i = 0; i < numClusters; i++) {
        if (cluster[i] > 0) {
          centroid[0] += points[i].fold(0.0, (a, b) => a + b) / cluster[i];
          centroid[1] += points[i].fold(0.0, (a, b) => a + b) / cluster[i];
        }
      }

      for (int i = 0; i < numClusters; i++) {
        if (cluster[i] > 0) {
          List<double> newCentroid = List.from(centroid);
          double distToNew = 0.0;
          for (int j = 0; j < numClusters; j++) {
            if (cluster[j] > 0) {
              double d = distance(points[j], newCentroid);
              if (d > 0.0) {
                distToNew += d;
              } else if (i != j) {
                distToNew += 1.0;
              }
            }
          }
          if (distToNew > dist) {
            centroid[0] -= points[i].fold(0.0, (a, b) => a + b) / cluster[i];
            centroid[1] -= points[i].fold(0.0, (a, b) => a + b) / cluster[i];
          } else if (distToNew == dist) {
            if (rng.nextDouble() < 0.5) {
              centroid[0] -= points[i].fold(0.0, (a, b) => a + b) / cluster[i];
              centroid[1] -= points[i].fold(0.0, (a, b) => a + b) / cluster[i];
            }
          }
        }
      }

      iterations++;
    }

    print('Cluster $iteration:');
    for (int i = 0; i < numClusters; i++) {
      print('  Cluster $i: ${points[i].map((p) => p.toString()).join(' ')}');
    }
    print('centroid: ${centroid.map((p) => p.toString()).join(' ')}');
    print('Converged in $iterations iteration(s).');

    if (bestDist == 0.0) {
      break;
    }
  }
}

