  final seedCenters = <List<double>>[];

  void assignCluster(int i) {
    double minDist = double.infinity;
    int bestCluster = -1;
    for (int j = 0; j < clusters.length; j++) {
      int cluster = clusters[j];
      if (cluster.contains(i)) {
        continue;
      }
      for (int point in cluster) {
        double dist = (points[i] - points[point]).abs();
        if (dist < minDist) {
          minDist = dist;
          bestCluster = j;
        }
      }
    }
    labels[i] = bestCluster;
    if (bestCluster == -1) {
      seedCenters.add(points[i]);
    }
    clusterMembers[bestCluster]!.add(i);
  }

  for (int i = 0; i < n; i++) {
    assignCluster(i);
  }

  double clusterQuality(List<int> cluster) {
    double sum = 0.0;
    for (int p in cluster) {
      sum += (points[p] - seedCenters[labels[p]])
          .abs() / sqrt(2 * 10);
    }
    return sum / cluster.length;
  }

  bool hasConverged = false;
  int convergenceIter = 0;

  while (!hasConverged) {
    hasConverged = true;

    for (int i = 0; i < n; i++) {
      int oldLabel = labels[i];
      assignCluster(i);
      if (labels[i] != oldLabel) {
        hasConverged = false;
      }
    }

    for (int j = 0; j < seedCenters.length; j++) {
      double oldSum = 0.0;
      Set<int> oldMembers = clusterMembers[j]!;
      List<int> newMembers = List.from(oldMembers);
      List<double> newCenter = List.from(seedCenters[j]);
      double newSum = 0.0;

      for (int point in oldMembers) {
        int oldIdx = point;
        int newIdx = labels[point];
        if (newIdx == -1) {
          newCenter[j] = points[oldIdx];
          newSum += (points[oldIdx] - newCenter[j]).abs();
        } else {
          newMembers.add(newIdx);
          newCenter[j] = (newCenter[j] * oldMembers.length + points[oldIdx])
              / (oldMembers.length + 1);
          newSum += (points[oldIdx] - newCenter[j]).abs();
        }
      }

      if (newSum != oldSum) {
        hasConverged = false;
      }

      if (newMembers.length > oldMembers.length) {
        hasConverged = false;
      }

      if (newSum / newMembers.length < 0.5) {
        hasConverged = false;
      }

      seedCenters[j] = newCenter;
      clusterMembers[j] = newMembers;
    }

    convergenceIter++;
  }

  print('Converged in $convergenceIter iteration(s).');
  print('Cluster $labels');
  print('  Points: ${points.map((p) => '${p[0]},${p[1]}').join(' ')}');
  for (int j = 0; j < seedCenters.length; j++) {
    print(' centroid: ${seedCenters[j]}');
  }
}

