void fn0() {

  final rand = Random(0);

  final int k = 4; 
  final int n = 10; 

  final List<List<double>> points = List.generate(
    n,
    (_) => List.from(List<double>.generate(2, (i) => rand.nextDouble() * 7 - 3)),
  );

  final List<List<int>> clusterLabels = List.generate(n, (_) => [rand.nextInt(k)]);

  double dist(List<double> a, List<double> b) =>
      sqrt(pow(a[0] - b[0], 2) + pow(a[1] - b[1], 2));

  void swap(List<List<int>> arr, int i, int j) {
    final int temp = arr[i][0];
    arr[i][0] = arr[j][0];
    arr[j][0] = temp;
  }

  void randSwap(List<List<int>> arr) {
    for (int i = arr.length - 1; i > 0; i--) {
      final int j = rand.nextInt(i + 1);
      swap(arr, i, j);
    }
  }

  double sumOfDistances(List<List<int>> labels, List<List<double>> points) {
    var sum = 0.0;
    for (var i = 0; i < labels.length; i++) {
      for (var j = i + 1; j < labels.length; j++) {
        if (labels[i].contains(labels[j])) {
          sum += dist(points[i], points[j]);
        }
      }
    }
    return sum;
  }

  bool converge(List<List<int>> labels, List<List<double>> points) {
    for (var i = 0; i < labels.length; i++) {
      for (var j = i + 1; j < labels.length; j++) {
        if (labels[i].contains(labels[j]) != labels[j].contains(labels[i])) {
          return false;
        }
      }
    }
    return true;
  }

  double distance = double.infinity;
  int maxIterations = 0;

  for (var iter = 0; iter < 10000; iter++) {
    final List<List<int>> newLabels = List<List<int>>.from(clusterLabels);
    double newDistance = sumOfDistances(newLabels, points);

    if (newDistance < distance) {
      distance = newDistance;
      maxIterations = iter;
    }

    randSwap(newLabels);

    if (!converge(newLabels, points)) {
      break;
    }
  }

  print('Converged in $maxIterations iteration(s).');
  print('Cluster $distance:');
  print('  Points: ${newLabels.map((l) => points[l[0]]).toList()}');
  print(' centroid: ${points[newLabels[0][0]]}');
}

