void fn0() {

  final rand = Random(0);
  final points = [
    [1.0, 2.0],
    [2.0, 2.5],
    [2.0, 4.0],
    [4.0, 3.5],
    [3.5, 5.0],
    [3.5, 7.0],
    [5.0, 4.5],
    [4.5, 5.0],
  ];

  const int k = 3;

  List<int> clusterIds = List.filled(points.length, -1);
  for (int i = 0; i < points.length; i++) {
    clusterIds[i] = i;
  }

  double dist(List<int> a, List<int> b) {
    int d = (a[0] - b[0]).abs() + (a[1] - b[1]).abs();
    return sqrt(d);
  }

  double calcWithinClusterDist(List<int> cluster) {
    double sum = 0.0;
    for (int i = 0; i < cluster.length; i++) {
      int j = cluster[i];
      sum += dist(points[i], points[j]);
    }
    return sum;
  }

  double calcWithinClusterDist(List<List<int>> clusters) {
    double sum = 0.0;
    for (final cluster in clusters) {
      sum += calcWithinClusterDist(cluster);
    }
    return sum;
  }

  double calcBetweenClusterDist(List<int> clusterA, List<int> clusterB) {
    double sum = 0.0;
    for (int i = 0; i < clusterA.length; i++) {
      int j = clusterA[i];
      sum += dist(points[j], points[i]);
    }
    for (int i = 0; i < clusterB.length; i++) {
      int j = clusterB[i];
      sum += dist(points[j], points[i]);
    }
    return sum;
  }

  double calcBetweenClusterDist(List<List<int>> clusters) {
    double sum = 0.0;
    for (final clusterA in clusters) {
      for (final clusterB in clusters) {
        if (clusterA != clusterB) {
          sum += calcBetweenClusterDist(clusterA, clusterB);
        }
      }
    }
    return sum;
  }

  double calObjective() {
    double cost = 0.0;
    for (int i = 0; i < clusters.length; i++) {
      for (final cluster in clusters) {
        if (cluster.contains(i)) {
          double w = calcWithinClusterDist(cluster);
          cost += w;
          for (final neighbor in cluster) {
            if (neighbor != i) {
              double b = calcBetweenClusterDist(cluster, neighbor);
              cost += b;
            }
          }
        }
      }
    }
    return cost;
  }

  double convergenceTreshold = 0.01;

  bool converged = false;
  double bestCost = double.infinity;
  List<List<int>> bestClusters = [];
  List<int> bestClusterIds = List.filled(points.length, -1);

  while (!converged) {
    List<List<int>> clusters = [];
    List<int> clusterIds = List.filled(points.length, -1);
    for (int i = 0; i < points.length; i++) {
      clusterIds[i] = rand.nextInt(clusters.length);
      if (clusterIds[i] == clusters.length) {
        clusters.add(List.from(points[i]));
        clusterIds[i] = clusters.length - 1;
      }
    }

    double cost = calObjective();
    if (cost < bestCost) {
      bestCost = cost;
      bestClusters = List.from(clusters);
      bestClusterIds = List.from(clusterIds);
      converged = true;
    }

    if (cost < convergenceTreshold) {
      converged = true;
    }
  }

  print('Cluster $converged');
  print('Converged in ${bestCost} iteration(s).');
  print('Best cost: $bestCost');
  print('Best centroids:');
  for (int i = 0; i < bestClusters.length; i++) {
    print('  Cluster $i: ${bestClusters[i].map((p) => '${p[0]}, ${p[1]}').join(' ')}');
  }
  print('  Points: ${bestClusterIds.map((p) => '${p[0]}, ${p[1]}').join(' ')}');
  print('  centroid: ${bestClusters.first.first}');
  print('  Within-cluster dist: ${calcWithinClusterDist(bestClusters.first)}');
  print('  Between-cluster dist: ${calcBetweenClusterDist(bestClusters)}');
}

