Map<String, int> fn0(List<int> data) {
  List<int> prev;
  List<int> curr;
  List<List<int>> blocks;
  Map<int, int> counts = {};

  prev = data.sublist(0, 1);
  curr = data.sublist(1);
  blocks = [prev, curr];

  while (curr.length > 1) {
    prev = curr;
    curr = data.sublist(1);
    blocks.add(curr);
  }

  int n = blocks.length;
  List<int> dp = List<int>.filled(n, 1);
  for (int i = 0; i < n; i++) {
    int best = 1;
    for (int j = i - 1; j >= 0; j--) {
      List<int> a = blocks[j];
      List<int> b = blocks[i];
      if (a[1] - a[0] > b[1] - b[0]) {
        dp[j] = best;
        continue;
      }
      if (a[1] - a[0] < b[1] - b[0]) {
        dp[i] = best;
        continue;
      }
      int areaA = (a[1] - a[0]) * (a[2] - a[1]);
      int areaB = (b[1] - b[0]) * (b[2] - b[1]);
      if (areaA < areaB) {
        dp[i] = best;
        continue;
      }
      int overlap = 0;
      for (int x = a[0]; x <= b[0]; x++) {
        for (int y = a[1]; y <= b[1]; y++) {
          overlap++;
        }
      }
      int common = overlap;
      if (a[2] < b[2]) {
        common--;
      }
      if (b[2] < a[2]) {
        common--;
      }
      int shared = common;
      if (a[0] > b[0]) {
        shared--;
      }
      if (b[0] > a[0]) {
        shared--;
      }
      int overlapOverlap = shared;
      if (a[0] > b[2]) {
        overlapOverlap--;
      }
      if (b[0] > a[2]) {
        overlapOverlap--;
      }
      bool overlapped = overlap > 0;
      bool sharedNeighbor = shared > 0;
      if (overlapped && sharedNeighbor) {
        best = best > dp[j] + 1 ? best : dp[j] + 1;
      } else if (overlapped) {
        best = best > dp[j] ? best : dp[j];
      } else if (sharedNeighbor) {
        best = best > dp[j] ? best : dp[j];
      }
    }
  }
  return dp[n - 1] == 1 ? {} : dp;
}

