Map<String, int> fn0(List<List<int>> schedule, List<int> openDays, List<int> openTimes, List<int> reservedHours) {
  List<List<int>> times = [];
  for (int i = 0; i < schedule.length; i++) {
    times.add([schedule[i][0], schedule[i][1]]);
  }
  times.sort((a, b) => a[0].compareTo(b[0]));
  Map<String, int> result = {};
  int count = 0;
  for (int i = 0; i < times.length; i++) {
    if (times[i][0] < openDays[0] || times[i][0] > openDays[1]) {
      continue;
    }
    int start = times[i][0];
    int end = times[i][1];
