      continue;
    }
    if (start < openDays[0] && end > openDays[1]) {
      continue;
    }
    List<int> reserved = [];
    for (int j = 0; j < reservedHours.length; j++) {
      int r = reservedHours[j];
      if (start < r && r < end) {
        reserved.add(r);
      }
    }
    if (reserved.isEmpty) {
      result["$start-$end"] = (result["$start-$end"] ?? 0) + 1;
      count++;
      continue;
    }
    reserved.sort();
    int mergeCount = 0;
    int prevEnd = 0;
    for (int r in reserved) {
      if (r < prevEnd) {
        mergeCount++;
      }
      prevEnd = r;
    }
    result["$start-$end"] = (result["$start-$end"] ?? 0) + mergeCount;
    count += mergeCount;
  }
  return result;
}

