  final cols = timetable[0].length;
  final List<List<int>> arr = List.generate(rows, (i) => List.filled(cols, timetable[i][i]));
  final List<List<int>> directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];
  final Map<String, int> counts = {};
  for (var i = 0; i < rows; i++) {
    for (var j = 0; j < cols; j++) {
      int curr = arr[i][j];
      for (var d in directions) {
        int nextI = i + d[0];
        int nextJ = j + d[1];
        if (nextI >= 0 && nextI < rows && nextJ >= 0 && nextJ < cols) {
          int next = arr[nextI][nextJ];
          if (next > curr) {
            curr = next;
          }
        }
      }
      counts['$curr'] = (counts['$curr'] ?? 0) + 1;
    }
  }
  return counts;
}

